# Set a grade's rate. Validate first so a bad grade or percent is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.rate.RecordRateSet
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
  govern: [ transaction ]
# Import lines of name,grade,terms,contact, in order: a line naming a person on the sheet (by name
# or alias) edits them as the person form would; any other line adds a person as the form would.
# Every line is checked before any is saved: one refused line refuses the import and writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateImportPeople
  next: add
add:
  class: net.officefloor.hq.app.person.AddImportedPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImportPeople
  govern: [ transaction ]
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** A percent: 0.00 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RateRequest request,
            Out<RateRequest> body, Out<Rate> rate, Out<Actor> actor) throws InvalidSheetRequestException {
        if (request == null || request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetRequestException("The grade must be A, B or C");
        }
        String pct = request.pct() == null ? "" : request.pct().trim();
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidSheetRequestException("The rate must be a percent, 0.00 or more, with up to two decimals");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidSheetRequestException("The to-date may not be before the from-date");
        }
        actor.set(new Actor(request.user()));
        body.set(request);
        rate.set(new Rate(sheetId, request.grade(), new BigDecimal(pct).setScale(2), from, to));
    }

    /** A yyyy-mm-dd date, or null when blank. */
    private static LocalDate date(String value) throws InvalidSheetRequestException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.rate;

/** Body of a rate change: the grade (A, B or C), the percent, the from-date and to-date (yyyy-mm-dd,
 *  blank for none) and who makes the change. */
public record RateRequest(String grade, String pct, String from, String to, String user) {
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;

public class SaveRate {
    public void save(@Val Rate rate, Rates rates) {
        rates.save(rate);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the rate is saved, so a refused change writes no audit line. */
public class RecordRateSet {
    public void record(@Val RateRequest request, @Val Rate rate, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + request.user()
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() != null ? " from=" + rate.from() : "")
                + (rate.to() != null ? " to=" + rate.to() : ""));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRate {
    public void respond(@Val Rate rate, ObjectResponse<RateResponse> response) {
        response.send(RateResponse.from(rate));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A grade's rate on a sheet: a percent with two decimals, in force from `from` (null: from the beginning of time)
 *  through `to` (null: with no end). */
public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rates for each grade of each sheet; a grade has at most one per from-date (or none). */
@Repository
public class Rates {

    private final JdbcTemplate jdbc;

    public Rates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate on the sheet, by grade, then by from-date (the one with none first). */
    public List<Rate> onSheet(String sheetId) {
        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date FROM rate WHERE sheet_id = ? ORDER BY grade, from_key",
                (rs, i) -> {
                    Date from = rs.getDate("from_date");
                    Date to = rs.getDate("to_date");
                    return new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("pct"),
                            from != null ? from.toLocalDate() : null, to != null ? to.toLocalDate() : null);
                },
                sheetId);
    }

    /** How many levels of parent sheets a grade's rate is looked for in. */
    public static final int PARENT_LEVELS = 3;

    /** The grade's rate in force on `date`: the sheet's own (see {@link #ownPct}), else its parent's
     *  then, else the parent's parent's, up to {@link #PARENT_LEVELS} levels up; null when none has one. */
    public BigDecimal pct(String sheetId, String grade, LocalDate date) {
        String sheet = sheetId;
        for (int level = 0; sheet != null && level <= PARENT_LEVELS; level++) {
            BigDecimal pct = ownPct(sheet, grade, date);
            if (pct != null) return pct;
            sheet = parent(sheet);
        }
        return null;
    }

    /** The sheet's parent sheet id, or null when it names none. */
    public String parent(String sheetId) {
        return jdbc.query("SELECT parent_id FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getString("parent_id"), sheetId)
                .stream().filter(p -> p != null).findFirst().orElse(null);
    }

    /** The sheet's ancestors' rates, nearest first: each parent sheet up to {@link #PARENT_LEVELS}
     *  levels up, with every rate set on it. */
    public List<Inherited> inherited(String sheetId) {
        List<Inherited> inherited = new ArrayList<>();
        String sheet = parent(sheetId);
        for (int level = 1; sheet != null && level <= PARENT_LEVELS; level++) {
            inherited.add(new Inherited(level, sheet, onSheet(sheet)));
            sheet = parent(sheet);
        }
        return inherited;
    }

    /** The rates of an ancestor sheet `level` levels up (1 for the parent). */
    public record Inherited(int level, String sheetId, List<Rate> rates) {
    }

    /** The grade's rate in force on `date` set on the sheet itself: the one with the latest from-date
     *  on or before it, or null when there is none or that one's to-date is before `date`. */
    public BigDecimal ownPct(String sheetId, String grade, LocalDate date) {
        return jdbc.query("SELECT pct, to_date FROM rate WHERE sheet_id = ? AND grade = ? AND from_key <= ?"
                + " ORDER BY from_key DESC LIMIT 1",
                (rs, i) -> {
                    Date to = rs.getDate("to_date");
                    return to != null && to.toLocalDate().isBefore(date) ? null : rs.getBigDecimal("pct");
                }, sheetId, grade, Date.valueOf(date))
                .stream().filter(p -> p != null).findFirst().orElse(null);
    }

    /** Set the grade's rate from its from-date, replacing the one it had for that from-date. */
    public void save(Rate rate) {
        Date from = rate.from() != null ? Date.valueOf(rate.from()) : null;
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                rate.sheetId(), rate.grade(), from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), from, rate.to() != null ? Date.valueOf(rate.to()) : null);
    }
}

